function parseResponse(raw) {
  try {
    const clean = raw.replace(/^```json\s*/i,"").replace(/^```\s*/i,"").replace(/```\s*$/,"").trim();
    return JSON.parse(clean);
  } catch {
    return { intro: raw, suggestions: [], closing: null };
  }
}

function SuggestionCard({ wine, index }) {
  const [expanded, setExpanded] = useState(false);
  const accent = CARD_ACCENTS[index % CARD_ACCENTS.length];
  const hasExtras = wine.pairing || wine.highlight;
  return (
    <div style={{ borderRadius: 16, border: "1.5px solid var(--color-border-tertiary)", background: "var(--color-background-primary)", overflow: "hidden", boxShadow: expanded ? "0 6px 24px rgba(0,0,0,0.10)" : "0 1px 4px rgba(0,0,0,0.05)", transition: "box-shadow 0.2s" }}>
      <div style={{ height: 5, background: accent }} />
      <div style={{ padding: "18px 20px" }}>
        {wine.badge && <span style={{ display: "inline-block", marginBottom: 10, fontSize: 11, fontWeight: 700, letterSpacing: "0.05em", textTransform: "uppercase", color: accent, background: accent + "18", padding: "3px 10px", borderRadius: 999 }}>{wine.badge}</span>}
        <p style={{ margin: "0 0 4px", fontSize: 20, fontWeight: 800, color: "var(--color-text-primary)", lineHeight: 1.25 }}>{wine.name}</p>
        {(wine.producer || wine.region) && <p style={{ margin: "0 0 12px", fontSize: 14, color: "var(--color-text-secondary)" }}>{[wine.producer, wine.region].filter(Boolean).join(" · ")}</p>}
        {wine.format && <div style={{ display: "inline-block", marginBottom: 16, padding: "6px 14px", borderRadius: 999, background: accent, color: "#fff", fontSize: 14, fontWeight: 700 }}>{wine.format}</div>}
        <p style={{ margin: 0, fontSize: 16, lineHeight: 1.75, color: "var(--color-text-primary)" }}>{wine.reason}</p>
        {hasExtras && <>
          <button onClick={() => setExpanded(e => !e)} style={{ marginTop: 14, padding: "7px 14px", fontSize: 14, fontWeight: 600, color: accent, background: accent + "12", border: "none", borderRadius: 999, cursor: "pointer" }}>
            {expanded ? "▲ Hide details" : "▼ Pairing & details"}
          </button>
          {expanded && <div style={{ marginTop: 14, padding: "14px 16px", borderRadius: 12, background: "var(--color-background-secondary)", display: "flex", flexDirection: "column", gap: 10 }}>
            {wine.pairing && <div style={{ display: "flex", gap: 10, alignItems: "flex-start" }}><span style={{ fontSize: 18, flexShrink: 0 }}>🍽</span><p style={{ margin: 0, fontSize: 15, lineHeight: 1.6, color: "var(--color-text-primary)" }}><strong>Pairs with:</strong> {wine.pairing}</p></div>}
            {wine.highlight && <div style={{ display: "flex", gap: 10, alignItems: "flex-start" }}><span style={{ fontSize: 18, flexShrink: 0 }}>✦</span><p style={{ margin: 0, fontSize: 15, lineHeight: 1.6, color: "var(--color-text-secondary)", fontStyle: "italic" }}>{wine.highlight}</p></div>}
          </div>}
        </>}
      </div>
    </div>
  );
}

function AssistantMessage({ content }) {
  const parsed = parseResponse(content);
  return (
    <div style={{ display: "flex", alignItems: "flex-start", gap: 12 }}>
      <img src={ODA_LOGO} alt="Oda" style={{ width: 32, height: 32, borderRadius: "50%", flexShrink: 0, objectFit: "contain", border: "0.5px solid var(--color-border-tertiary)", background: "var(--color-background-secondary)", marginTop: 2 }} />
      <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 14 }}>
        {parsed.intro && <div style={{ padding: "12px 16px", borderRadius: "4px 16px 16px 16px", background: "var(--color-background-secondary)", fontSize: 16, lineHeight: 1.75, color: "var(--color-text-primary)" }}>{parsed.intro}</div>}
        {parsed.suggestions?.length > 0 && <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>{parsed.suggestions.map((w, i) => <SuggestionCard key={i} wine={w} index={i} />)}</div>}
        {parsed.closing && <p style={{ margin: 0, fontSize: 14, lineHeight: 1.65, color: "var(--color-text-secondary)", fontStyle: "italic", paddingLeft: 2 }}>{parsed.closing}</p>}
      </div>
    </div>
  );
}

